use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};const R:&str="/home/ubuntu/src/zopro-perf-work/positive-gauss-caller175";fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn main(){assert!(!r("repair-pins.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(r("build-pins.json")).unwrap()).unwrap();let allowed=["native.rs","native-helper","source-audit.json","source/crates/zopro-core/src/msm/g2_borrowed.rs"].map(|s|r(s).display().to_string());for(p,h)in &mut pins{let actual=hash(p);if actual!=*h{assert!(allowed.contains(p),"unexpected drift:{p}");*h=actual;}}for p in["repair.rs","repair","repair-pins.rs","repair-pins","repair-plan.json","repair.json","build-plan.json","build-pins.json","initial-g2-borrowed.rs.txt","initial-source-audit.json","initial-native.rs.txt","initial-driver.rs.txt","driver.rs","driver","state.rs"]{pins.insert(r(p).display().to_string(),hash(r(p)));}let v:Value=json!(pins);fs::write(r("repair-pins.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Pinned repaired ON build with{}inputs; frozen/OFF successful work inherited",pins.len());}
